def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.

    This function utilizes dynamic programming to find two paths from the top-left corner to
    the bottom-right corner of the grid which maximize the sum of the values collected. Each
    value can be collected at most once, even if both paths pass through it.

    Args:
    - N (int): The size of the grid (N x N).
    - grid_values (List[Tuple[int, int, int]]): A list of tuples where each tuple contains
      the x-coordinate, y-coordinate, and value to be placed on the grid at that position.
      The list is terminated by a tuple with all zeros.

    Returns:
    - int: The maximum sum of values collected on the two paths.
    """
    # Create a 2D grid initialized with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the provided values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # DP table to store the maximum value collected by two paths
    dp = [[[[0] * N for _ in range(N)] for _ in range(N)] for _ in range(N)]

    # Initialize the starting point for both paths
    dp[0][0][0][0] = grid[0][0]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for k in range(N):
                for l in range(N):
                    if i == 0 and j == 0:
                        continue
                    if k == 0 and l == 0:
                        continue
                    max_value = 0

                    # Check all possible previous positions for both paths
                    if i > 0 and k > 0:
                        max_value = max(max_value, dp[i-1][j][k-1][l])
                    if i > 0 and l > 0:
                        max_value = max(max_value, dp[i-1][j][k][l-1])
                    if j > 0 and k > 0:
                        max_value = max(max_value, dp[i][j-1][k-1][l])
                    if j > 0 and l > 0:
                        max_value = max(max_value, dp[i][j-1][k][l-1])

                    if i != k or j != l:
                        dp[i][j][k][l] = max_value + grid[i][j] + grid[k][l]
                    else:
                        dp[i][j][k][l] = max_value + grid[i][j]

    return dp[N-1][N-1][N-1][N-1]

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.

    This function utilizes dynamic programming to find two paths from the top-left corner to
    the bottom-right corner of the grid which maximize the sum of the values collected. Each
    value can be collected at most once, even if both paths pass through it.

    Args:
    - N (int): The size of the grid (N x N).
    - grid_values (List[Tuple[int, int, int]]): A list of tuples where each tuple contains
      the x-coordinate, y-coordinate, and value to be placed on the grid at that position.
      The list is terminated by a tuple with all zeros.

    Returns:
    - int: The maximum sum of values collected on the two paths.

    Examples:
    >>> max_value_on_paths(2, [(1, 2, 1), (2, 1, 2), (0, 0, 0)])
    3
    >>> max_value_on_paths(8, [
    ...     (2, 3, 13), (2, 6, 6), (3, 5, 7), (4, 4, 14),
    ...     (5, 2, 21), (5, 6, 4), (6, 3, 15), (7, 2, 14),
    ...     (0, 0, 0)])
    67
    """
    if N <= 0:
        return 0

    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize dp array
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N * 2 - 1)]
    dp[0][0][0] = grid[0][0]

    # Fill dp array
    for step in range(1, 2 * N - 1):
        for i1 in range(max(0, step - (N - 1)), min(step + 1, N)):
            j1 = step - i1
            if j1 < 0 or j1 >= N:
                continue
            for i2 in range(max(0, step - (N - 1)), min(step + 1, N)):
                j2 = step - i2
                if j2 < 0 or j2 >= N:
                    continue
                if i1 != i2 or j1 != j2:
                    value = grid[i1][j1] + grid[i2][j2]
                else:
                    value = grid[i1][j1]

                for pi1 in [i1 - 1, i1]:
                    for pj1 in [j1 - 1, j1]:
                        if pi1 < 0 or pj1 < 0:
                            continue
                        for pi2 in [i2 - 1, i2]:
                            for pj2 in [j2 - 1, j2]:
                                if pi2 < 0 or pj2 < 0:
                                    continue
                                dp[step][i1][j1] = max(dp[step][i1][j1],
                                                     dp[step-1][pi1][pj1] + value)

    return max(0, dp[2 * N - 2][N - 1][N - 1])

def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.
    """
    def is_valid_combination(a, b, c):
        digits = set(str(a) + str(b) + str(c))
        return len(digits) == 9 and all(d.isdigit() and 1 <= int(d) <= 9 for d in digits)

    combinations = []
    for a in range(100, 1000):
        b = 2 * a
        c = 3 * a
        if 100 <= b < 1000 and 100 <= c < 1000:
            if is_valid_combination(a, b, c):
                combinations.append((a, b, c))

    return sorted(combinations)

