def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product that can be obtained by inserting K multiplication signs into the number string.

    Parameters:
    num_str (str): A string representing the number string.
    N (int): An integer representing the length of the number string.
    K (int): An integer representing the number of multiplication signs to insert.

    Returns:
    int: The maximum product that can be obtained.
    """
    if K == 0:
        return int(num_str)

    # Initialize a 2D list to store the maximum product up to each position with a certain number of multiplications
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: no multiplication sign used, product is the number itself up to that position
    for i in range(1, N + 1):
        dp[i][0] = int(num_str[:i])

    # Fill the dp table
    for i in range(1, N + 1):
        for k in range(1, K + 1):
            for j in range(k, i + 1):
                dp[i][k] = max(dp[i][k], dp[j - 1][k - 1] * int(num_str[j - 1:i]))

    return dp[N][K]

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product that can be obtained by inserting K multiplication signs into the number string.

    Parameters:
    num_str (str): A string representing the number string.
    N (int): An integer representing the length of the number string.
    K (int): An integer representing the number of multiplication signs to insert.

    Returns:
    int: The maximum product that can be obtained by inserting K multiplication signs into the number string.
    """
    if K == 0:
        return int(num_str)
    if K >= N - 1:
        return 0  # More multiplication signs than possible segments

    # dp[i][j] will store the maximum product using j multiplication signs for the first i+1 digits
    dp = [[0] * (K + 1) for _ in range(N)]

    for i in range(N):
        dp[i][0] = int(num_str[:i+1])

    for j in range(1, K + 1):
        for i in range(j, N):
            max_prod = 0
            for p in range(j-1, i):
                left_part = dp[p][j-1]
                right_part = int(num_str[p+1:i+1])
                product = left_part * right_part
                if product > max_prod:
                    max_prod = product
            dp[i][j] = max_prod

    return dp[N-1][K]

def max_product(num_str: str, N: int, K: int) -> int:
    if K >= N - 1:
        return int(num_str) if K == N - 1 else 0

    def backtrack(start, partitions):
        if len(partitions) == K + 1:
            product = 1
            for part in partitions:
                product *= int(part) if part else 0
            return product

        max_prod = 0
        for end in range(start + 1, N + 1):
            current_partition = num_str[start:end]
            if not current_partition.startswith('0') or current_partition == '0':
                max_prod = max(max_prod, backtrack(end, partitions + [current_partition]))

        return max_prod

    return backtrack(0, [])

