def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn_parts):
        total = 0
        for i, part in enumerate(isbn_parts[:-1]):
            total += (10 - i) * int(part)
        checksum = (11 - (total % 11)) % 11
        return 'X' if checksum == 10 else str(checksum)

    # Remove hyphens and split the ISBN into parts
    parts = isbn.replace('-', '')
    isbn_parts = [parts[i:i+1] for i in range(0, len(parts))]

    # Calculate the expected checksum
    expected_checksum = calculate_checksum(isbn_parts)

    # Compare the expected checksum with the provided checksum
    if expected_checksum == isbn_parts[-1]:
        return "Right"
    else:
        # Construct the corrected ISBN
        corrected_isbn = '-'.join(isbn_parts[:-1]) + '-' + expected_checksum
        return corrected_isbn

def verify_isbn(isbn: str) -> str:
    # Remove hyphens and check the length
    cleaned_isbn = isbn.replace('-', '')
    if len(cleaned_isbn) != 10:
        raise ValueError("ISBN must be a 10-character string without hyphens.")

    # Calculate the checksum
    total = 0
    for i in range(9):
        if not cleaned_isbn[i].isdigit():
            raise ValueError("First 9 characters of ISBN must be digits.")
        total += int(cleaned_isbn[i]) * (10 - i)

    # Calculate the expected checksum digit
    expected_checksum = 11 - (total % 11)
    if expected_checksum == 10:
        expected_checksum_char = 'X'
    elif expected_checksum == 11:
        expected_checksum_char = '0'
    else:
        expected_checksum_char = str(expected_checksum)

    # Compare the calculated checksum with the provided one
    provided_checksum_char = cleaned_isbn[9]
    if provided_checksum_char == 'X' and expected_checksum_char == '10':
        provided_checksum_char = 'X'

    if provided_checksum_char == expected_checksum_char:
        return "Right"
    else:
        corrected_isbn = cleaned_isbn[:9] + expected_checksum_char
        return f"{corrected_isbn[0]}-{corrected_isbn[1:4]}-{corrected_isbn[4:9]}-{corrected_isbn[9]}"

def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn):
        isbn_digits = isbn.replace('-', '')[:-1]
        total = sum((10 - i) * int(digit) for i, digit in enumerate(isbn_digits))
        checksum = (11 - (total % 11)) % 11
        return 'X' if checksum == 10 else str(checksum)

    if len(isbn) != 13 or '-' not in isbn:
        raise ValueError("Invalid ISBN format")

    checksum = isbn[-1]
    expected_checksum = calculate_checksum(isbn)

    if checksum == expected_checksum:
        return "Right"
    else:
        corrected_isbn = isbn[:-1] + expected_checksum
        return corrected_isbn

