    if n == 1:
        return 1 if m == 0 else 0

    # dp[i][j] will be the number of ways to pass so that the ball ends up with student i after j passes
    dp = [[0] * (m + 1) for _ in range(n)]

    # Base case: after 0 passes, the ball is with student 0
    dp[0][0] = 1

    # Fill the dp table
    for j in range(1, m + 1):
        for i in range(n):
            dp[i][j] = dp[(i - 1) % n][j - 1] + dp[(i + 1) % n][j - 1]

    # The result is the number of ways to be back at student 0 after m passes
    return dp[0][m]

