def count_partitions(n: int, k: int, x: int) -> int:
    def helper(n, k, x, memo):
        if n < 0 or k < 0:
            return 0
        if n == 0 and k == 0:
            return 1
        if k == 0 or n == 0:
            return 0
        if (n, k, x) in memo:
            return memo[(n, k, x)]

        # Include at least x in the current partition
        count = helper(n - x, k - 1, x, memo)

        # Skip the current partition if it can be reduced further
        if x + 1 <= n:
            count += helper(n, k, x + 1, memo)

        memo[(n, k, x)] = count
        return count

    # Adjust n by subtracting k * x to account for the minimum value constraint
    adjusted_n = n - k * x
    if adjusted_n < 0:
        return 0

    memo = {}
    return helper(adjusted_n, k, 0, memo)

