def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Create a DP array to store the maximum volume that can be achieved for each capacity
    dp = [0] * (V + 1)

    # Iterate over each item's volume
    for volume in volumes:
        # Update the DP table from back to front to avoid overwriting results from the same iteration
        for capacity in range(V, volume - 1, -1):
            if dp[capacity - volume] + volume > dp[capacity]:
                dp[capacity] = dp[capacity - volume] + volume

    # The maximum volume that can be occupied in the box
    max_occupied_volume = dp[V]

    # The minimum remaining space is the difference between the box's capacity and the max occupied volume
    return V - max_occupied_volume

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a boolean DP array where dp[i] will be True if a volume i can be achieved with the given items
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: a volume of 0 can always be achieved with zero items

    # Iterate over each item's volume
    for volume in volumes:
        # Traverse the DP array backwards to avoid overwriting values that are yet to be computed in this iteration
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be achieved which is less than or equal to V
    max_achievable_volume = 0
    for j in range(V, -1, -1):
        if dp[j]:
            max_achievable_volume = j
            break

    # The minimum remaining space is the total volume minus the maximum achievable volume
    return V - max_achievable_volume

